  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const states = new Map()
  const stats = new Map()
  const out = []
  let started = false
  let prev = null
  let allowed = 0
  let denied = 0

