          if (word === 'bucket') {
            p = { kind: 'bucket', name: f[1], capacity: int('capacity', f[2], 1), refill: int('refill', f[3], 0), per: int('per', f[4], 1) }
          } else {
            p = { kind: 'window', name: f[1], limit: int('limit', f[2], 0), span: int('span', f[3], 1) }
          }
          if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
          policies.set(f[1], p)
        }
      } else if (word === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        if (!WORD.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (prev !== null && tick < prev) throw new Fail(`tick ${f[1]} is before tick ${prev}`)
        started = true
        prev = tick
        const key = f[2]
        let best = null
        for (const prefix of routes.keys()) {
          if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
        }
        let refused = null
        if (best !== null) {
          const names = routes.get(best)
          const sts = names.map((n) => {
            const id = `${best}\0${key}\0${n}`
            // state is per policy per key, shared across routes only by key
