          if (refused === null) names.forEach((n, j) => record(policies.get(n), sts[j], tick))
        }
        const s = stats.get(key) ?? { a: 0, d: 0 }
        stats.set(key, s)
        if (refused === null) { s.a++; allowed++ } else { s.d++; denied++ }
        out.push(refused === null ? `${f[1]} ${key} allow` : `${f[1]} ${key} deny ${refused}`)
      } else {
        throw new Fail(`unknown directive ${word}`)
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })

  if (mode === 'replay') return out
  const res = [...stats.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    .map((k) => `${k} allowed=${stats.get(k).a} denied=${stats.get(k).d}`)
  res.push(`total allowed=${allowed} denied=${denied}`)
  return res
}

